            "contact_page.hero_subtitle": "Ponte en contacto con Mosco Events",
            "contact_page.whatsapp_card_text": "¿Tienes dudas sobre los eventos, inscripciones o normativa? Contacta directamente con nosotros por WhatsApp.",
